const WILD_SLOTS = {
  composition: ['famM', 'countM', 'countG', 'everyWave'],
  pacing: ['trick'],
  reward: ['rewardM', 'rich'],
  price: ['priceM', 'heartPM', 'heartN'],



  mutator: ['heartGrow', 'heartRoof', 'noHeartMarket', 'noHeartField', 'skyTear', 'magnet', 'eliteN', 'eliteW0', 'timedT', 'groundDenied', 'skyBand', 'glass', 'hearts'],
};







function wrunWildPool(slot) {
  const seen = {}, pool = [];
  for (const v of WVARIANTS) {
    if (v.wildcard) continue;
    const sig = WILD_SLOTS[slot].map((c) => JSON.stringify(v[c] === undefined ? null : v[c])).join('|');
    if (seen[sig]) continue;
    seen[sig] = 1; pool.push(v);
  }
  return pool;
}
function wrunRollWild(base) {
  const out = Object.assign({}, base);
  const donors = {};
  for (const slot in WILD_SLOTS) {
    const pool = wrunWildPool(slot);
    const d = pool[Math.floor(Math.random() * pool.length)];
    donors[slot] = d.k;
    for (const cell of WILD_SLOTS[slot]) { delete out[cell]; if (d[cell] !== undefined) out[cell] = d[cell]; }
  }
  out.wildDonors = donors;
  return out;
}






















const WTUNES = [




  { k: 'EASY', name: 'EASY', m: 0.75, dh: 2,
    cap: 'enemies take and deal less, steel costs less, hearts come easier' },
  { k: 'MEDIUM', name: 'MEDIUM', m: 1.00, dh: 0,
    cap: 'the game as it is written — the baseline every number here was tuned against' },
  { k: 'HARD', name: 'HARD', m: 1.35, dh: -1,
    cap: 'enemies take and deal more, steel costs more, hearts come harder' },
];


const WTUNE_FIELDS = ['hpM', 'hpG', 'aggM', 'fireG', 'priceM', 'heartN', 'heartPM', 'crHp', 'crAgg', 'crFire'];
function wtuneRow(k) { return WTUNES.find((t) => t.k === k) || WTUNES[1]; }

































const WRUNTYPES = ['V1', 'V28', 'V29'];

function wrtRow(k) { return WVARIANTS.find((v) => v.k === k) || WVARIANTS[0]; }






function wtuneMint(base, k) {
  const t = wtuneRow(k);
  if (t.m === 1 && !t.dh) return null;
  const out = {};
  for (const key in base) out[key] = base[key];
  for (const f of WTUNE_FIELDS) if (typeof base[f] === 'number') out[f] = base[f] * t.m;



  if (typeof out.heartN === 'number') out.heartN = Math.max(1, Math.round(out.heartN));
  if (typeof base.hearts === 'number') out.hearts = Math.max(1, base.hearts + t.dh);
  out.tune = t.k;
  return out;
}
function wvar() {
  if (WRUN.tuned) return WRUN.tuned;
  const row = WVARIANTS.find((v) => v.k === WRUN.variant) || WVARIANTS[0];
  return (row.wildcard && WRUN.rolled) ? WRUN.rolled : row;
}



























function crescMin() { return (gameMode === 'wave' && WRUN.on) ? Math.floor(WRUN.runT / 60) : 0; }
function crescHp() { const v = wvar(); return 1 + crescMin() * (v.crHp || 0); }






















