function wrunEdgeX(i, pad, step) {
  const half = ((typeof window !== 'undefined' ? window.innerWidth : 1200) / 2) / WORLD_ZOOM;
  const side = i % 2 ? 1 : -1;






















  const st = step || 35;
  const room = side > 0
    ? (STREET_MAX - 120) - (player.x + half + pad + 200)
    : (player.x - half - pad - 200) - (STREET_MIN + 120);
  const slots = Math.max(1, Math.floor(room / st));
  const lap = Math.floor(i / slots);
  const reach = (i % slots) * st + ((lap % 4) * st) / 4;
  let x = Math.max(STREET_MIN + 120, Math.min(STREET_MAX - 120,
    player.x + side * (half + pad + Math.random() * 200 + reach)));
  if (Math.abs(x - player.x) < half) {
    x = Math.max(STREET_MIN + 120, Math.min(STREET_MAX - 120,
      player.x - side * (half + pad + Math.random() * 200 + reach)));
  }
  return x;
}














