function glassPut(surf, el, str0, x, y, maxW, px, weight, align, plate) {
  const fl69 = Math.max(6, FIT_FLOOR);
  let p = scaleSnap(px);
  while (p > fl69 && textPx(str0, p, weight, GLASS.FONT) > maxW) p = scaleStepDown(p);
  let str = String(str0);
  if (textPx(str, p, weight, GLASS.FONT) > maxW) {
    while (str.length > 1 && textPx(str + '\u2026', p, weight, GLASS.FONT) > maxW) str = str.slice(0, -1);
    str = str + '\u2026';
  }
  ctx.font = glassFont(p, weight);
  const prevA = ctx.textAlign;
  if (align) ctx.textAlign = align;
  ctx.fillText(str, x, y);
  ctx.textAlign = prevA;
  const w = textPx(str, p, weight, GLASS.FONT);
  if (HUDLAB.probe) {
    const a = align || prevA || 'left';
    const x0 = a === 'center' ? x - maxW / 2 : a === 'right' ? x - maxW : x;
    (HUDLAB.fit = HUDLAB.fit || []).push({ surface: surf, el, x: x0, y: y - p, w: maxW, h: p + 4,
      ink: ctx.fillStyle, alpha: ctx.globalAlpha, bold: /^[6-9]00/.test(String(weight || '')), plate: plate || null,
      texts: [{ s: str, px: p, w }] });
  }
  return w;
}
function fitPut(surf, el, str0, x, y, maxW, px, weight, align, plate) {
  const p = fitOneLine(str0, maxW, px, weight, FIT_FLOOR);
  const str = fitClip(str0, maxW, p, weight);
  ctx.font = (weight ? weight + ' ' : '') + p + "px 'Courier New', monospace";
  const prevA = ctx.textAlign;
  if (align) ctx.textAlign = align;
  ctx.fillText(str, x, y);
  ctx.textAlign = prevA;
  const w = textPx(str, p, weight);
  if (HUDLAB.probe) {
    const a = align || prevA || 'left';
    const x0 = a === 'center' ? x - maxW / 2 : a === 'right' ? x - maxW : x;




    (HUDLAB.fit = HUDLAB.fit || []).push({ surface: surf, el, x: x0, y: y - p, w: maxW, h: p + 4,
      ink: ctx.fillStyle, alpha: ctx.globalAlpha, bold: /^[6-9]00/.test(String(weight || '')), plate: plate || null,
      texts: [{ s: str, px: p, w }] });
  }
  return w;
}








