  if (c && c.merge) c = WDECK.find((q) => q.k === (c.k === 'melee' ? 'swordarm' : c.k === 'jetpack' ? 'afterburn' : c.k === 'electric' ? 'shock' : c.k === 'shadowveil' ? 'shadow' : c.k === 'rocketpod' ? 'rockets' : 'trigger')) || c;
