const GUARD = {
  HITS: 3,
  ROOF: 8,
  R: 44,
  T: 5,
  KEY: 1.6,
  GAP: 0.14,
  SPIN: 0.5,
  CRACK: 0.3,
  KICK: 5,
  STEPS: 10,
  led: { capped: 0, lost: 0 },
};


function shieldGuard(n) {
  if (shieldHearts === 0) shieldAcc = 0;
  if (!(n > 0)) return 0;



  const want = shieldHearts + n;
  shieldHearts = Math.min(GUARD.ROOF, want);
  if (want > GUARD.ROOF) { GUARD.led.capped++; GUARD.led.lost += want - GUARD.ROOF; }
  if (shieldHearts > shieldCap) shieldCap = shieldHearts;
  return shieldHearts;
}




function shieldCrack() {
  const cap = Math.max(1, shieldCap, shieldHearts + 1);
  const step = Math.max(0, Math.min(2, cap - shieldHearts - 1));
  shieldCrackT = GUARD.CRACK;
  if (shieldHearts > 0) { SFX.clink(step); return; }



  shieldCap = 0;
  SFX.shieldBreak();
  rings.push({ x: player.x, y: player.y - 55, age: 0, life: 0.55, maxR: 150, color: '#ffd24a', wd: 6 });
  for (let k = 0; k < 22; k++) spawnParticle(player.x, player.y - 55, { vy: -30, spread: 460, life: 0.6, r: 3.4, color: k % 3 ? '#ffd24a' : '#fff3c9' });
  shake = Math.min(shake + 4, 12);
}











function drawOrbRing(e) {
  if (!rbOrbLive(e) && !rbOrbBurstLive(e)) return;
  const cx = e.x, cy = bodyCY(e);
  const rOut = RBORB.R, rIn = rOut - RBORB_ART.T;
  const spin = gameTime * RBORB_ART.SPIN;
  const plate = (a0, a1, ri, ro, col, alpha) => {
    const n = Math.max(3, Math.ceil(RBORB_ART.STEPS * Math.abs(a1 - a0) / (Math.PI * 2)));
    ctx.globalAlpha = alpha;
    ctx.fillStyle = col;
    ctx.beginPath();
    for (let s = 0; s <= n; s++) { const a = a0 + (a1 - a0) * (s / n); const x = cx + Math.cos(a) * ro, y = cy + Math.sin(a) * ro; if (s === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); }
    for (let s = n; s >= 0; s--) { const a = a0 + (a1 - a0) * (s / n); ctx.lineTo(cx + Math.cos(a) * ri, cy + Math.sin(a) * ri); }
    ctx.closePath(); ctx.fill();
  };
  const TAU = Math.PI * 2;
  ctx.save();






  if (rbOrbBurstLive(e)) {
    const easeB = (e.orbBurstT - gameTime) / RBORB_ART.BURST;
    const rB = rOut + (1 - easeB) * RBORB_ART.T * RBORB_ART.BLOW;




    plate(0, TAU, rB - RBORB_ART.T * 1.15, rB + RBORB_ART.T * 1.15, 'rgba(8,20,32,0.6)', 0.6 * easeB);
    plate(0, TAU, rB - RBORB_ART.T * 0.6, rB + RBORB_ART.T * 0.6, '#fffdf0', easeB);
    if (HUDLAB.probe) HUDLAB.orbBurst = { x: Math.round(cx), y: Math.round(cy), r: +rB.toFixed(2), ease: +easeB.toFixed(3) };
  }
  if (!rbOrbLive(e)) { ctx.globalAlpha = 1; ctx.restore(); return; }

  plate(0, TAU, rIn - RBORB_ART.KEY, rOut + RBORB_ART.KEY, 'rgba(8,20,32,0.82)', 1);

  plate(0, TAU, rIn, rOut, '#3aa8c8', 0.9);


  const cap = Math.max(1, rbOrbCap()), share = TAU / cap, gap = share * 0.12;
  for (let i = 0; i < cap; i++) {
    const a0 = spin + i * share + gap * 0.5, a1 = a0 + share - gap;
    const filled = (e.orb.bank || 0) > i;
    plate(a0, a1, rIn, rOut, filled ? '#bff3ff' : '#17607a', filled ? 1 : 0.85);
    if (filled) plate(a0, a1, rIn, rIn + RBORB_ART.T * 0.4, '#ffffff', 0.8);
  }










  for (let k = 0; k < RBORB_ART.NOTCH; k++) {
    const a = -spin * 1.7 + k * (TAU / RBORB_ART.NOTCH);
    const rt0 = rOut - RBORB_ART.T * 0.34, rt1 = rOut + RBORB_ART.KEY * 0.6;
    plate(a - RBORB_ART.NW, a + RBORB_ART.NW, rt0, rt1, 'rgba(8,20,32,0.9)', 1);
    plate(a + RBORB_ART.NW, a + RBORB_ART.NW * 1.9, rt0, rt1, '#eafcff', 0.95);
  }
  ctx.globalAlpha = 1;
  ctx.restore();
  if (HUDLAB.probe) {
    HUDLAB.orb = { x: Math.round(cx), y: Math.round(cy), rOut: +rOut.toFixed(2), rIn: +rIn.toFixed(2),
      bank: e.orb.bank || 0, cap: cap, notch: RBORB_ART.NOTCH, spin: +(spin % TAU).toFixed(3) };
  }
}












