function duckMusic(ev) {
  bedDuck((DUCK.EV[ev] || DUCK.EV.hurt).bed);
  if (!musicGain || !audioCtx) return;
  const t = audioCtx.currentTime, g = musicGain.gain;
  g.cancelScheduledValues(t);
  g.setValueAtTime(g.value, t);
  g.linearRampToValueAtTime(volMusic * DUCK.MUS.depth, t + DUCK.MUS.atk);
  g.linearRampToValueAtTime(volMusic, t + DUCK.MUS.rel);
}
function veilActive() { return VEIL.t > 0; }
function veilBegin() {
  if (dead || veilActive() || shockActive() || VEIL.meter < 0.4) return;
  if (TURBO.phase) { VEIL.skyRefusedAt9 = gameTime; return; }
  if (gameTime < (VEIL.lockUntil || 0)) { tone({ f0: 220, f1: 150, dur: 0.1, type: 'square', vol: 0.06, cue: 'pilot' }); return; }
  VEIL.t = Math.min(VEIL.meter, VEIL.dur);
  rmbVeiled = true;
  if (WRUN.on && WRUN.tAcc) { WRUN.tAcc.veilN++; WRUN.tAcc.vT0 = gameTime; }
  VEIL.harvestN = 0;
  VEIL.refundM = VEIL.meter; VEIL.wasGrounded = player.grounded;
  player.vx /= SMOKE_DIL;
  player.grounded = false;
  player.vy = 0;
  SMOKE.trail.length = 0;
  SMOKE.lastX = player.x; SMOKE.lastY = player.y;
  SMOKE.trail.push({ x: player.x, y: player.y - 44 });
  veilSmoke(player.x, player.y - 40, 10);
  rings.push({ x: player.x, y: player.y - 44, age: 0, life: 0.14, maxR: 44, color: '#e6c8ff', wd: 3 });
  rings.push({ x: player.x, y: player.y - 44, age: -0.04, life: 0.18, maxR: 74, color: '#9f5af0', wd: 2 });
  shake = Math.min(shake + 2, 6);
  for (let k = 0; k < 6; k++) spawnParticle(player.x, player.y - 44, { vy: -50, spread: 220,
    life: 0.8 + Math.random() * 0.5, r: 1.1 + Math.random() * 0.9, color: k % 2 ? '#ffd76a' : '#ffecb0' });
  VEIL.trailT = 0;
  veilSmoke(player.x, player.y - 40, 8);
  SFX.veilOn();
}
function veilEnd() {
  if (veilActive()) {
    if (WRUN.on && WRUN.tAcc && WRUN.tAcc.vT0 !== undefined) { WRUN.tAcc.veilT = +((WRUN.tAcc.veilT || 0) + (gameTime - WRUN.tAcc.vT0)).toFixed(1); WRUN.tAcc.vT0 = undefined; }
    player.vx *= SMOKE_DIL; player.vy *= SMOKE_DIL; for (const b of REFL_BODIES) if (b.column && b.on && !b.dead) { b.vx *= SMOKE_DIL; b.vy *= SMOKE_DIL; }    
    if (gameTime - VEIL.bufJump < 0.3) { spaceJustPressed = true; }
    veilSmoke(player.x, player.y - 40, 8);
    rings.push({ x: player.x, y: player.y - 44, age: 0, life: 0.2, maxR: 46, color: '#c9f2ff', wd: 2 });
    for (let k74 = 0; k74 < 4; k74++) spawnParticle(player.x, player.y - 44, { vy: -60, spread: 200, life: 0.3, r: 2, color: '#e6f6ff' });
    SFX.veilOff();
  }
  VEIL.bufJump = -9;
  RBWAR.graceUntil = gameTime + (SANDBOX.on ? SANDBOX.rb.grace : 0.45);
  VEIL.exitAt = gameTime;
  VEIL.t = 0;
}
function veilCancelQuiet() {
  player.vx *= SMOKE_DIL;
  VEIL.t = 0;
  VEIL.meter = Math.min(VEIL.dur, VEIL.refundM || VEIL.meter);
  SMOKE.trail.length = 0; SMOKE.fuse.length = 0;
  VEIL.bufJump = -9;
  if (VEIL.wasGrounded && player.y > groundY() - 6) { player.y = groundY(); player.vy = 0; player.grounded = true; }
}
function rmbUp() {
  if (SHADOW.holdT < 0) return;
  const wasVeiled = rmbVeiled;
  rmbVeiled = false;
  if (wasVeiled && SHADOW.holdT < RMB_HOLD_T) { veilCancelQuiet(); shadowRelease(); }
  else if (wasVeiled) { smokeDetonate(); veilEnd(); SHADOW.holdT = -1; }
  else if (SHADOW.holdT < RMB_HOLD_T) shadowRelease();
  else SHADOW.holdT = -1;
}
