function applyShadowUp(k, quiet) {
  const u = SHADOW_UP[k], v = u.vals[u.lv];
  if (k === 'scharge') SHADOW.max = v;
  else if (k === 'sregen') SHADOW.regen = v;
  else if (k === 'sdmg') SHADOW.dmg = v;
  else if (k === 'phantom') { SHADOW.phantom = v; if (v >= 1 && PHANTOM9.max < 3) { PHANTOM9.max = 3; PHANTOM9.charges = 3; } }
  else if (k === 'pbank') { PHANTOM9.max = v; PHANTOM9.charges = Math.min(PHANTOM9.charges, PHANTOM9.max); }
  else if (k === 'pregen') PHANTOM9.regen = v;
  else if (k === 'phlife') SHADOW.phlife = v;
  else if (k === 'pfire') SHADOW.pfire = v;
  else if (k === 'mstab') SHADOW.mstab = v;
  else if (k === 'vspd') { VEIL.spdRung = v; if (!SANDBOX.on && !quiet) veilRungSave(); }
  else if (k === 'vvert') { VEIL.vRung = v; if (!SANDBOX.on && !quiet) veilRungSave(); }
  else if (k === 'vdur') { VEIL.dur = v; VEIL.meter = v; if (!SANDBOX.on && !quiet) veilRungSave(); }
  else if (k === 'vrefill') { VEIL.refill = v; if (!SANDBOX.on && !quiet) veilRungSave(); }
  else if (k === 'vslow') SMOKE.burn = v;
  else if (k === 'vtrail') SMOKE.bite = v;
  else if (k === 'vwide') SMOKE.wakeW = v;
  else if (k === 'vlife') SMOKE.wakeN = v;
}
