  ctx.strokeStyle = 'rgba(190,238,255,0.55)'; ctx.lineWidth = 6.5 * s10;
  ctx.beginPath(); ctx.arc(-8 * s10, 0, r10, -1.0, 1.0); ctx.stroke();
  ctx.strokeStyle = 'rgba(255,255,255,0.92)'; ctx.lineWidth = 2.6 * s10;
