function drawMuzzleFlash() {
  if (muzzleFx.t <= 0) return;
  const T = 0.085;
  const t = 1 - muzzleFx.t / T;
  const a = 1 - t;
  const mx = muzzleFx.x, my = muzzleFx.y, fc = muzzleFx.facing;





  const gr = 1 + (Math.sqrt(Math.max(1, muzzleFx.n || 1)) - 1) * 0.25;
  ctx.save();
  ctx.translate(mx, my);

  ctx.strokeStyle = 'rgba(255,244,220,' + (0.12 * a) + ')';
  ctx.lineWidth = 1.5 * gr;
  for (const rr of [10 + t * 26, 5 + t * 38]) {
    ctx.beginPath(); ctx.arc(fc * 6, 0, rr * gr, -0.9, 0.9); ctx.stroke();
  }
  let g = ctx.createRadialGradient(fc * 16, 0, 0, fc * 16, 0, 22 * gr);
  g.addColorStop(0, 'rgba(255,235,200,' + (0.1 * a) + ')');
  g.addColorStop(1, 'rgba(255,235,200,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(fc * 16, 0, 22 * gr, 0, Math.PI * 2); ctx.fill();

  ctx.lineCap = 'round';
  ctx.rotate(Math.sin(muzzleFx.seed * 9) * 0.22);
  const rays = [[0, 20], [0.55, 9], [-0.55, 9], [2.3, 7], [-2.3, 7], [Math.PI, 6]];
  for (const [ra, rl] of rays) {
    const L = rl * gr * (1 + Math.sin(muzzleFx.seed * 7 + ra) * 0.25) * (1 - t * 0.55);
    const ca = Math.cos(ra) * fc, sa = Math.sin(ra);
    ctx.strokeStyle = 'rgba(255,214,110,' + (0.85 * a) + ')';
    ctx.lineWidth = 3 * gr;
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(ca * L, sa * L); ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,' + (0.95 * a) + ')';
    ctx.lineWidth = 1.4 * gr;
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(ca * L * 0.72, sa * L * 0.72); ctx.stroke();
  }










  const cr = 8 * gr * (1 - t * 0.4);
  g = ctx.createRadialGradient(0, 0, 0, 0, 0, cr);
  g.addColorStop(0, 'rgba(255,255,255,' + a + ')');
  g.addColorStop(0.6, 'rgba(255,224,140,' + (0.8 * a) + ')');
  g.addColorStop(1, 'rgba(255,180,60,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, cr, 0, Math.PI * 2); ctx.fill();
  const hr = 7 * (1 - t * 0.4) * (1 + (gr - 1) * 0.3);
  g = ctx.createRadialGradient(0, 0, 0, 0, 0, hr);
  g.addColorStop(0, 'rgba(255,255,255,' + a + ')');
  g.addColorStop(0.72, 'rgba(255,252,236,' + (0.92 * a) + ')');
  g.addColorStop(1, 'rgba(255,240,190,0)');
  ctx.fillStyle = g;
  ctx.beginPath(); ctx.arc(0, 0, hr, 0, Math.PI * 2); ctx.fill();
  ctx.restore();
}

