function drawMartinBoard() {
  if (!martinNear()) return;
  const bid = martinBid();
  const word = bid > 1.005 ? 'OVER LIST' : (bid < 0.995 ? 'BACK OF LIST' : 'LIST');
  const n = Math.floor(diamondBalance());
  const pay = Math.max(1, Math.round(n * bid));
  const x = MARTIN.x, y = groundY() - 128;
  const offer = 'E  —  SELL ' + n + ' ◆  →  ' + pay + ' STYLE';
  const head = 'BID  ' + bid.toFixed(2);
  ctx.save();
  ctx.textAlign = 'center';








  ctx.font = '700 ' + TYPE.chip + 'px ui-monospace, Menlo, monospace';
  const wOffer = ctx.measureText(offer).width;
  ctx.font = '800 ' + TYPE.title + 'px ui-monospace, Menlo, monospace';
  const halfW = Math.max(wOffer, ctx.measureText(head).width) / 2 + 13;
  ctx.fillStyle = 'rgba(10,13,19,0.93)';
  ctx.fillRect(x - halfW, y - 34, halfW * 2, 50);
  ctx.strokeStyle = 'rgba(255,215,102,0.30)'; ctx.lineWidth = 1;
  ctx.strokeRect(x - halfW + 0.5, y - 33.5, halfW * 2 - 1, 49);
  ctx.fillStyle = bid >= 1 ? '#7ff0a8' : '#ffcf6b';
  ctx.fillRect(x - halfW, y - 34, halfW * 2, 2);
  ctx.fillText(head, x, y - 13);
  ctx.font = '600 ' + TYPE.chip + 'px ui-monospace, Menlo, monospace';
  ctx.fillStyle = '#9fb0c8';
  ctx.fillText(word, x, y);
  ctx.fillStyle = '#ffd766';
  ctx.font = '700 ' + TYPE.chip + 'px ui-monospace, Menlo, monospace';
  ctx.fillText(offer, x, y + 13);
  ctx.restore();
}
