function updateSwarm(dt) {
  if (swarm.countdown > 0 && !swarm.active) {
    const prev = swarm.countdown;
    swarm.countdown -= dt;
    if (prev > 10 && swarm.countdown <= 10) tone({ f0: 880, f1: 880, dur: 0.12, type: 'square', vol: 0.07 });
    if (Math.floor(prev) !== Math.floor(swarm.countdown) && swarm.countdown <= 5 && swarm.countdown > 0)
      tone({ f0: 660, f1: 660, dur: 0.09, type: 'square', vol: 0.07 });
    if (swarm.countdown <= 0) launchSwarm();
  }
  if (swarm.active && swarm.spawnQueue > 0) {
    swarm.spawnT -= dt;
    if (swarm.spawnT <= 0) {
      swarm.spawnT = 0.12;
      swarm.spawnQueue--;
      const side = Math.random() < 0.5 ? -1 : 1;
      const cx = player.x + side * (700 + Math.random() * 900);
      const alt = 140 + Math.random() * 760;
      const half = 400 + Math.random() * 700;
      spawnDrone(cx, alt, cx - half, cx + half, true);
      const d = enemies[enemies.length - 1];
      d.swarm = true;
      d.hp += swarm.hpBoost || 0;
      d.cooldown = 0.4 + Math.random() * 1.6;
    }
  }
}
