function annDialRows() {
  const out = [];
  for (const k of Object.keys(ANN_CADENCE)) {
    const C = ANN_CADENCE[k];
    if (C.perMin <= 0) continue;
    const why = ANN_DIAL_WHY[k] || '';
    const lo = k.charAt(0) + k.slice(1).toLowerCase();


    const dMin = C.min, dRate = C.perMin;
    out.push({ id: 'annMin' + k, label: lo.toUpperCase() + ' HOLD', cap: 'seconds ' + lo + ' waits before the same line repeats \u00b7 WAVE-LIVE',
      note: 'The minimum gap between two ' + lo + ' callouts on the SAME key \u2014 ' + why + '. Ships ' + dMin + 's, derived in `notes/ANNOUNCER-DOCTRINE.md` \u00a73 from the lane\u2019s own physics (three slots, each held 2.4s). Raising it makes this class rarer and lets its events pass unspoken; lowering it toward zero lets one key repeat until the per-minute ceiling notices, which is up to a full minute of the same line. **WAVE-LIVE** \u2014 a readout dial changes no difficulty, so the no-cheat lock that keeps enemy dials desk-only has nothing to say about it.',
      def: dMin, min: 0, max: dMin * 10, step: 0.1, lim: 'roof ' + (dMin * 10) + ' \u2014 ten times shipped',
      get: () => ANN_CADENCE[k].min, set: (v) => { ANN_CADENCE[k].min = Math.max(0, Math.min(dMin * 10, v)); }, fmt: (v) => v.toFixed(1) + 's' });
    out.push({ id: 'annRate' + k, label: lo.toUpperCase() + ' CEILING', cap: 'most ' + lo + ' callouts a minute; over it the class goes quiet \u00b7 WAVE-LIVE',
      note: 'The per-minute ceiling for ' + lo + ' \u2014 ' + why + '. Ships ' + dRate + '/min against the lane\u2019s own 75/min of capacity (three slots at 2.4s), and the seven ceilings sum to 52 by design so a burst has room. Raising it lets the class talk over the others when the lane is hot; lowering it drops earned events on the floor. **MEASURED, NOT PROMISED:** `wavesim [AWN]` prints every class against its ceiling from a staged 60-second window every run. **WAVE-LIVE.**',
      def: dRate, min: 0, max: dRate * 10, step: 1, lim: 'roof ' + (dRate * 10) + ' \u2014 ten times shipped',
      get: () => ANN_CADENCE[k].perMin, set: (v) => { ANN_CADENCE[k].perMin = Math.max(0, Math.min(dRate * 10, Math.round(v))); } });
  }
  return out;
}





