function annRate(cls) {
  let n = 0;
  for (const f of ANN_LOG.fires) if (f.cls === cls) n++;
  return n;
}
function annAllow(cls, key) {
  const C = ANN_CADENCE[cls];
  if (!C) return false;
  const now = gameTime;
  if (C.perMin <= 0) { ANN_LOG.led.said++; return true; }




  const seen = ANN_LOG.last[key];
  if (seen !== undefined && now >= seen && now - seen < C.min) { ANN_LOG.led.hushed++; return false; }

  for (let i = ANN_LOG.fires.length - 1; i >= 0; i--) {
    const f = ANN_LOG.fires[i];
    if (now - f.t >= 60 || f.t > now) ANN_LOG.fires.splice(i, 1);
  }
  if (annRate(cls) >= C.perMin) { ANN_LOG.led.capped++; return false; }
  ANN_LOG.last[key] = now;
  ANN_LOG.fires.push({ cls: cls, t: now });
  ANN_LOG.led.said++;
  return true;
}
