function spawnTutDummy(dx, hp, live) {




  const w = tutWall();
  const reach = 260;
  let x = player.x + dx;
  if (x > w.hi - 20) x = player.x - dx;
  if (x < w.lo + 20) x = Math.min(w.hi - 20, player.x + reach);
  x = Math.max(w.lo + 20, Math.min(w.hi - 20, x));
  const e = { kind: 'rival', x, dy: 0, hp, state: 'walk', anim: 'idle',
    animTime: 0, t: 1, dir: -1, fade: 1, tutDummy: true };








  if (live) {
    e.state = 'patrol'; e.anim = 'walk';
    e.cooldown = 0; e.threw = false; e.type = 0;
    e.x0 = Math.max(w.lo + 20, x - 120); e.x1 = Math.min(w.hi - 20, x + 120);
  }
  enemies.push(e);
  return e;
}











function spawnTutDrone(dx, alt, posture) {
  const w = tutWall();
  let x = player.x + dx;
  if (x > w.hi - 20) x = player.x - dx;
  x = Math.max(w.lo + 20, Math.min(w.hi - 20, x));
  const e = { x, __tutX: x, __tutDy: posture === 'parked' ? 30 : Math.max(80, alt || 220),
    dy: posture === 'parked' ? 30 : Math.max(80, alt || 220),
    hp: posture === 'shooter' ? 26 : 6, drone: true, fam: 'drone', type: 0,
    dir: player.x > x ? 1 : -1, state: 'tut', t: 99, anim: 'idle', animTime: 0,
    threw: false, cooldown: 99999, fade: 1, bob: 0, burst: 0, tutDummy: true };
  if (posture === 'shooter') { e.state = 'hover'; e.cooldown = 1.0; e.t = 99; }
  enemies.push(e);
  return e;
}




