function tutRingsArm(baseX) {
  const w = tutWall();



  TUTRINGS.list = [
    { x: Math.min(w.hi - 90, baseX + 170), alt: 480, hit: false },
    { x: Math.min(w.hi - 90, baseX + 310), alt: 660, hit: false },
    { x: Math.min(w.hi - 90, baseX + 450), alt: 840, hit: false },
    { x: Math.min(w.hi - 90, baseX + 560), alt: 1020, hit: false },
  ];
  TUTRINGS.on = true;
}
function tutRingsTick() {
  if (!TUTRINGS.on) return false;
  let all = true, idx = 0;
  for (const r of TUTRINGS.list) {
    idx++;
    if (!r.hit) {
      const dxR = player.x - r.x, dyR = (groundY() - player.y + 34) - r.alt;
      if (dxR * dxR + dyR * dyR <= TUTRINGS.R * TUTRINGS.R) {
        r.hit = true;
        tone({ f0: 520 + idx * 140, f1: 880 + idx * 160, dur: 0.14, type: 'sine', vol: 0.09 });
        rings.push({ x: r.x, y: groundY() - r.alt, age: 0, life: 0.35, maxR: 90, color: '#7dff9a', wd: 3 });
      }
    }
    if (!r.hit) all = false;
  }
  return all;
}


