const RND_CHUNK = 512;
const RNDB = { list: [], map: new Map(), trails: new Map(), heads: new Map() };
function rndBucket(fill, r) {
  const k = fill + '|' + r;
  let q = RNDB.map.get(k);
  if (!q) { q = { fill, r, n: 0, xs: new Float64Array(256), ys: new Float64Array(256) }; RNDB.map.set(k, q); RNDB.list.push(q); }
  return q;
}
function rndDisc(q, x, y) {
  if (q.n === q.xs.length) { const xs = new Float64Array(q.n * 2), ys = new Float64Array(q.n * 2); xs.set(q.xs); ys.set(q.ys); q.xs = xs; q.ys = ys; }
  q.xs[q.n] = x; q.ys[q.n] = y; q.n++;
}
function rndFillDiscs(q) {
  const r = q.r, xs = q.xs, ys = q.ys, n = q.n;
  for (let i = 0; i < n; i += RND_CHUNK) {
    const e = Math.min(n, i + RND_CHUNK);
    ctx.beginPath();
    for (let k = i; k < e; k++) { const x = xs[k], y = ys[k]; ctx.moveTo(x + r, y); ctx.arc(x, y, r, 0, Math.PI * 2); }
    ctx.fill();
  }
  q.n = 0;
}
function rndHeadBucket(hue) {
  let q = RNDB.heads.get(hue);
  if (!q) { q = rndBucket(hue ? rbRoundTint(hue).head : 'rgba(206,150,255,0.9)', 6.5); RNDB.heads.set(hue, q); }
  return q;
}
function rndTrail(hue, hist) {
  let t = RNDB.trails.get(hue);
  if (!t) { t = { hue, n: 0, t: 0, pts: new Float64Array(2048), cnt: new Int32Array(128) }; RNDB.trails.set(hue, t); }
  const L = hist.length, need = ((L + 1) >> 1) + 1;
  while ((t.n + need) * 2 > t.pts.length) { const p = new Float64Array(t.pts.length * 2); p.set(t.pts); t.pts = p; }
  if (t.t === t.cnt.length) { const c = new Int32Array(t.cnt.length * 2); c.set(t.cnt); t.cnt = c; }
  let c = 0, i = 0;
  for (; i < L; i += 2) { const h = hist[i]; t.pts[t.n * 2] = h.x; t.pts[t.n * 2 + 1] = h.y; t.n++; c++; }
  if (i !== L + 1) { const h = hist[L - 1]; t.pts[t.n * 2] = h.x; t.pts[t.n * 2 + 1] = h.y; t.n++; c++; }
  t.cnt[t.t++] = c;
}
const RND_AMBER = rndBucket('#ffd27a', 5.5), RND_PLAT = rndBucket('#e6dcff', 8.25), RND_SPEC = rndBucket('rgba(255,255,255,0.95)', 5.5);
