function pchipLive() {
  const out = [];
  for (const k in PCHIP_KINDS) {
    const K = PCHIP_KINDS[k];
    const t = K.left();
    if (!(t > 0)) continue;
    out.push({ k, K, t, f: Math.max(0, Math.min(1, t / K.DUR)) });
  }
  out.sort((a, b) => a.t - b.t);
  return out;
}





























const HYPEBAR = { H: 58, Y: 292, W: 800, LEN: 2.6, PAD: 18, SLIDE: 58, SLIDE_T: 0.14, EASE: 2.3, KIN: 6, RING_T: 0.55, GAP: 0.35, DEPTH: 4 };








const HYPEQ = { q: [], cool: 0, led: { raised: 0, queued: 0, evicted: 0, shown: 0 } };
const HYPE = { text: '', t: 0, y: 0, land: 0 };







function hypeLen() { return HYPEBAR.LEN; }
function hypeGap() { return HYPEBAR.GAP; }
function hypeDepth() { return HYPEBAR.DEPTH; }
function hypeSlideT() { return HYPEBAR.SLIDE_T; }



function hypeZone() {



  const wW = window.innerWidth;
  return { name: 'hypebar', x: Math.round(wW / 2 - HYPEBAR.W / 2), y: HYPEBAR.Y, w: HYPEBAR.W, h: HYPEBAR.H };
}
function hypeLive() { return HYPE.t > 0 && !!HYPE.text; }




function hypeRaise(text, pr) {
  if (!text) return;
  HYPEQ.led.raised++;
  HYPEQ.q.push({ text: String(text), pr: pr === undefined ? 2 : pr, age: 0 });



  if (HYPEQ.q.length > hypeDepth()) {
    HYPEQ.q.sort((a, b) => (b.pr - a.pr) || (a.age - b.age));
    const gone = HYPEQ.q.pop();
    HYPEQ.led.evicted++;
    void gone;
  }
  HYPEQ.led.queued = HYPEQ.q.length;
}


function hypeQPump(dt) {
  if (HYPEQ.cool > 0) HYPEQ.cool -= dt;
  if (hypeLive() || rbBannerBusy()) return;
  if (HYPEQ.cool > 0 || !HYPEQ.q.length) return;
  HYPEQ.q.sort((a, b) => (b.pr - a.pr) || (a.age - b.age));
  const next = HYPEQ.q.shift();
  HYPEQ.led.queued = HYPEQ.q.length;
  HYPEQ.led.shown++;
  HYPE.text = next.text;
  HYPE.t = hypeLen();
  HYPE.y = HYPEBAR.SLIDE;
  HYPE.land = 0;
}
function rbBannerBusy() { return false; }
function hypeTick(dt) {
  for (const w of HYPEQ.q) w.age += dt;
  hypeQPump(dt);
  if (HYPE.t <= 0) return;
  HYPE.t -= dt;
  if (HYPE.t <= 0) { HYPE.t = 0; HYPE.text = ''; HYPE.y = 0; HYPE.land = 0; HYPEQ.cool = hypeGap(); return; }












  if (HYPE.y > 0) {
    const p = Math.min(1, (hypeLen() - HYPE.t) / hypeSlideT());
    HYPE.y = HYPEBAR.SLIDE * Math.pow(1 - p, HYPEBAR.EASE);
    if (p >= 1 || HYPE.y < 1) { HYPE.y = 0; HYPE.land = hypeLen() - HYPE.t; }
  }
}
function pchipZone() {
  return { name: 'powerchips', x: PCHIP.X, y: PCHIP.Y, w: PCHIP.MAX * PCHIP.CH + (PCHIP.MAX - 1) * PCHIP.GAP, h: PCHIP.CH };
}




function drawHypeBar() {
  if (!hypeLive()) return;
  const z0 = hypeZone();
  const z = { name: z0.name, x: z0.x, y: z0.y + Math.round(HYPE.y), w: z0.w, h: z0.h };

  const a = Math.min(1, (hypeLen() - HYPE.t) * 4) * Math.min(1, HYPE.t * 2.5);
  const age = hypeLen() - HYPE.t;
  ctx.save();
  ctx.globalAlpha = Math.max(0, Math.min(1, a));



  if (HYPE.land > 0) {
    const sinceLand = age - HYPE.land;
    if (sinceLand >= 0 && sinceLand < HYPEBAR.RING_T) {
      const rr = sinceLand * 1100 + 30;
      ctx.save();
      ctx.strokeStyle = 'rgba(200,162,255,' + ((1 - sinceLand / HYPEBAR.RING_T) * 0.5).toFixed(3) + ')';
      ctx.lineWidth = Math.max(0.5, 4 - sinceLand * 5);
      ctx.beginPath();
      ctx.ellipse(z.x + z.w / 2, z.y + z.h / 2, rr, rr * 0.32, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }
  }
  ctx.fillStyle = 'rgba(8,10,16,0.82)';
  ctx.fillRect(z.x, z.y, z.w, z.h);
  hudRect('hypebar', z.x, z.y, z.w, z.h);
  ctx.fillStyle = '#c8a2ff';
  ctx.fillRect(z.x, z.y, z.w, 2);
  ctx.fillRect(z.x, z.y + z.h - 2, z.w, 2);
  hudRect('hypebar', z.x, z.y, z.w, 2);
  hudRect('hypebar', z.x, z.y + z.h - 2, z.w, 2);


  const sinceL = HYPE.land > 0 ? age - HYPE.land : -1;
  const punch = 2.25 + HYPEBAR.KIN * 0.675;
  const pop = (sinceL >= 0 && sinceL < hypeSlideT()) ? 1 + (hypeSlideT() - sinceL) * punch * 0.12 : 1;
  ctx.font = '700 ' + (30 * pop).toFixed(1) + 'px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  const tx = z.x + z.w / 2, ty = z.y + z.h / 2;





  ctx.strokeStyle = 'rgba(2,6,14,0.85)';
  ctx.lineWidth = 5;
  ctx.strokeText(HYPE.text, tx, ty);
  ctx.fillStyle = '#fff';
  ctx.fillText(HYPE.text, tx, ty);
  const tw = Math.min(z.w - HYPEBAR.PAD * 2, ctx.measureText(HYPE.text).width);
  hudRect('hypebar', Math.round(tx - tw / 2), Math.round(ty - 15), Math.round(tw), 30);
  ctx.globalAlpha = 1;
  ctx.restore();
  if (HUDLAB.probe) HUDLAB.hype = { text: HYPE.text, t: +HYPE.t.toFixed(3), a: +a.toFixed(3), zone: z,
    dy: +HYPE.y.toFixed(3), land: +HYPE.land.toFixed(3), age: +age.toFixed(3), pop: +pop.toFixed(4),
    ring: HYPE.land > 0 && sinceL >= 0 && sinceL < HYPEBAR.RING_T };
}
function drawPowerChips() {
  const live = pchipLive();
  if (HUDLAB.probe) HUDLAB.chips = [];
  PCHIP.led.live = live.length;
  PCHIP.led.drawn = 0; PCHIP.led.hidden = 0;
  if (!live.length) return;
  const n = Math.min(PCHIP.MAX, live.length);
  PCHIP.led.drawn = n; PCHIP.led.hidden = live.length - n;
  const CH = PCHIP.CH, R = CH * 0.36;
  for (let i = 0; i < n; i++) {
    const c = live[i];
    const x = PCHIP.X + i * (CH + PCHIP.GAP), y = PCHIP.Y;
    const warn = c.t < PCHIP.WARN && Math.sin(gameTime * 18) > 0;
    const col = warn ? (c.K.warnTint || c.K.tint) : c.K.tint;
    ctx.fillStyle = 'rgba(4,5,14,0.55)';
    ctx.fillRect(x, y, CH, CH);
    ctx.strokeStyle = 'rgba(255,255,255,0.10)'; ctx.lineWidth = 1;
    ctx.strokeRect(x + 0.5, y + 0.5, CH - 1, CH - 1);
    const cx = x + CH / 2, cy = y + CH / 2;
    ctx.strokeStyle = 'rgba(255,255,255,0.14)'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.stroke();
    ctx.strokeStyle = col; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(cx, cy, R, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * c.f); ctx.stroke();
    ctx.save(); ctx.translate(cx, cy);
    c.K.icon(ctx, CH * 0.5);
    ctx.restore();
    hudRect('powerchips', x, y, CH, CH);
    if (HUDLAB.probe) (HUDLAB.chips = HUDLAB.chips || []).push({ k: c.k, t: +c.t.toFixed(3), f: +c.f.toFixed(4), warn: !!warn, x: Math.round(x), r: R });
  }
}


